<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script nonce="<?=e(csp_nonce())?>">const base={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{font:{size:8}}},y:{ticks:{font:{size:8}}}}};function chart(id,type,labels,data){new Chart(document.getElementById(id),{type,data:{labels,datasets:[{data,borderWidth:1.5,pointRadius:type==='line'?1.5:0,fill:type==='line'?false:true,backgroundColor:type==='line'?'rgba(239,107,79,.16)':'rgba(239,107,79,.82)',borderColor:'#ec6a4f',tension:.25}]},options:base})}chart('equityChart','line',<?=json_encode($equityLabels)?>,<?=json_encode($equityData)?>);chart('balanceChart','line',<?=json_encode($balanceLabels)?>,<?=json_encode($balanceData)?>);chart('rChart','bar',<?=json_encode($rLabels)?>,<?=json_encode($rData)?>);chart('systemChart','bar',<?=json_encode($systemLabels)?>,<?=json_encode($systemData)?>);chart('monthChart','bar',<?=json_encode($monthLabels)?>,<?=json_encode($monthData)?>);</script>
